window.DOSIK=window.DOSIK||{};DOSIK["yc_drugcounsel"]={"1":[{"t":"table","title":"약물의 종류","head":["약물","특징"],"rows":[["대마","만성적인 대마초 오남용은 조현병과 같은 정신질환을 유발할 가능성을 높인다 · 대마 성분 중 CBD(Cannabidiol)는 의료용으로 사용된다 · 대마초보다 해시시가 THC 함유량이 더 높다 · THC는 엔도칸나비노이드(endocannabinoids) 수용체에 작용하며 감정, 인지, 지각 등에 영향을 미친다"],["펜타닐","의료용 진통제로 개발된 합성 마약이다 · 모르핀보다 약 100배 정도의 강력한 진통효과를 가진다 · 소량을 흡입해도 인체에 치명적이다 · 밀조된 펜타닐은 정확한 함량을 지키지 않아 더욱 위해하다"],["메스암페타민","‘필로폰’으로 알려져 있으며, ‘아이스’, ‘크리스탈’로 불린다"],["날부민","‘누바인’으로 불리며, 의료용 진통제로 사용한다"],["덱스트로메토르판","‘러미나’로 불리며, 진해거담제로 사용한다"],["MDMA","식욕감퇴제로 개발되었으며, ‘도리도리’, ‘엑스터시’로 불린다"]]}],"2":[{"t":"table","title":"중독 관련 용어","head":["용어","뜻"],"rows":[["금단(withdrawal)","물질 사용을 줄이거나 습관적 행위 등을 중단할 때 나타나는 증상"],["갈망(craving)","약물 또는 행위에 관련된 기억, 환경 자극에 의해 유발되는 조건화된 반응"],["의존(dependence)","물질을 과도하게 사용해서 남용의 부작용과 함께 내성과 금단증상으로 표현되는 상태"],["재발(relapse)","회복된 이후에 중독 증상이 다시 나타나는 것"],["전구약물","본래는 비활성이었다가 인체 내 효소에 의해 대사된 후 활성화되는 약물"]]}],"3":[{"t":"def","term":"젤리넥","text":"알코올 중독이 진행성 질병이라고 주장한다"},{"t":"flow","title":"젤리넥의 단계","steps":["1단계는 전 알코올 증상 단계로 사교적인 목적이며, 중독 여부와 상관이 없다","2단계는 전조 단계로 문제성 음주 단계이며 블랙아웃이 발생하나, 술의 문제에 대해서는 부인한다","3단계는 결정적 단계로 음주에 대한 통제력 상실이 나타난다"]}],"4":[{"t":"tree","title":"약물사용의 위험요인","root":"청소년 약물남용의 위험요인","branches":[["감각추구형","감정 조절 어려움은 약물사용의 위험요소로 작용할 수 있다"],["중독자의 부모","일관성 없는 양육태도를 가지고 있을 가능성이 높다"],["중독자 부모를 둔 청소년","태아일 때부터 약물이나 알콜에 노출되었을 가능성이 있다"],["부모의 음주","청소년의 음주에 대한 태도와 규범에 영향을 줄 수도 있다"]]},{"t":"table","title":"관찰되는 모습","head":["구분","모습"],"rows":[["언행","횡설수설하며 폭력적인 언행이 증가한다"],["생활하는 방","환각흡입 물질이나 빨대, 비닐봉지 등이 발견되는 경우가 있다"],["신체","충혈된 눈, 잦은 눈물, 손, 발 등의 경미한 떨림을 보이기도 한다"],["걸음","술 냄새가 나지 않는데도 술 취한 사람처럼 비틀거리기도 한다"]]}],"5":[{"t":"cause","title":"청소년 마약류 사범 증가","causes":["다크웹, SNS를 통한 접근성이 높아졌다","청소년들이 SNS, 포털사이트 검색 등에 쉽게 노출되어 호기심으로 구입하는 사례가 증가하고 있다"],"result":"청소년 마약류 사범이 증가하고 있다"},{"t":"table","title":"마약류 오남용 실태","head":["시기","실태"],"rows":[["2022년","향정신성의약품이 마약의 검거율보다 높다 · 투약사범이 밀수사범보다 많다"],["2017년 이후","19세 이하 마약류 사범이 증가하는 추세이다"],["2019년 이후","신종 마약류 적발이 증가하고 있다"],["의료용","식욕억제제, 마취제 등 의료용 마약류의 남용이 늘어나고 있다"]]},{"t":"cause","title":"예방교육","causes":["마약류는 중독성이 강하다"],"result":"예방교육이 중요하다"}],"6":[{"t":"tree","title":"약물남용 예방교육","root":"약물남용 예방모델과 예방교육","branches":[["대상","위험성에 노출되지 않은 사람들을 대상으로 한다는 점에서 사용예방이라고도 불린다"],["내용","법과 제도의 개선, 취약성 폐해 홍보 및 예방교육 프로그램 등이 포함된다"],["효과","사용위험이나 취약성을 감소시키고, 보호요인을 증가시키는 가장 이상적인 예방방법이다"],["평생교육","예방효과를 높이기 위해서는 평생교육이 중요하다"]]}],"7":[{"t":"tree","title":"담배 진단기준","root":"DSM-5 물질관련장애 진단기준","branches":[["갈망","담배에 대한 갈망감 혹은 욕구가 있다"],["조절 실패","담배 사용을 조절하려는 노력에도 불구하고 실패한다"],["효과 감소","동일량의 담배를 사용하지만 그 효과가 현저히 감소한다"]]},{"t":"flow","title":"물질사용장애","steps":["DSM-Ⅳ의 물질남용과 물질의존","물질사용장애로 일원화 하였다"]},{"t":"tree","title":"중독의 구분","root":"중독","branches":[["물질 관련 중독","중독을 유발할 수 있는 물질에 알코올, 담배, 카페인, 수면제 등이 포함되어 있다"],["비물질 관련 중독"]]},{"t":"def","term":"심각도","text":"증상수에 따라 경도, 중등도, 고도로 분류한다","ex":["11가지 증상 중 5개에 해당될 경우 중증도에 해당한다"]}],"8":[{"t":"tree","title":"알코올의존 선별도구","root":"선별 및 평가도구","branches":[["목적","간편하게 알코올의존을 선별할 수 있는 측정도구이다"],["구성","자기보고형 측정도구 4문항으로 구성되어 있다"],["기준","2문항 이상 ‘그렇다’라고 응답하면 알코올의존으로 선별된다"],["용도","음주문제 선별을 위한 1차적 검사도구로 사용되고 있다"]]}],"10":[{"t":"tree","title":"인지행동상담","root":"인지행동상담과 재발방지","branches":[["주의분산법","갈망을 다루기 위해 사용되는 방법이다"],["기본과제","약물에서 회복하도록 돕는 것과 일상생활을 잘하도록 하는 것이다"],["소크라테스식 논답법","사용한다"],["스트레스 관리기법과 문제해결법","가르친다"]]}],"12":[{"t":"vs","title":"집단상담","cols":[{"name":"장점","items":["집단에서 규칙을 지킴으로써 살아가는 방식을 배울 수 있다","다른 집단원들로부터 자신의 생각에 대해서 피드백을 받고 약물사용에 대한 왜곡된 신념을 발견할 수 있다","참여자의 고립감을 해소시켜 주고 안정감을 더할 수 있다","다른 사람의 회복과정을 목격함으로써 단약 동기를 가질 수 있다","개인상담보다 비용과 시간 측면에서 경제적일 수 있다","약물경험이 있는 또래들과 함께 지내며 약물을 줄이려는 경향이 강해 집단상담이 유용할 수 있다","집단상담에서 약물남용으로부터 회복을 간접체험 할 수 있다"]},{"name":"진행 원칙","items":["공감과 염려의 태도, 존중하는 목소리로 살피면서 진행한다","동료 간의 직면을 특정 사람을 집단으로부터 밀어내는 도구로 사용하지 않아야 한다","약물사용과 관련된 ‘지금-여기’의 주제에 대해 초점을 맞춘다","단약에 대한 내담자의 실수를 소중한 배움의 경험으로 연결되도록 한다"]}]}],"13":[{"t":"tree","title":"공동의존","root":"가족상담과 공동의존","branches":[["시기","행복한 가정에 사는 친구를 시기한다"],["부모 모두 술을 마시는 경우","자신도 닮고 싶어 한다"],["친구 관계","친구를 초대하지 않고, 친구 집에 놀러가지도 않는다"],["외로움","자신이 보호 받아야 할 어린아이라고 생각할 때 외로움을 느낀다"]]}],"14":[{"t":"vs","title":"자조모임과 회복공동체","cols":[{"name":"AA","items":["12단계를 기초로 하여 알콜 없는 만족한 삶을 영위하는 방법을 제안한다","구성원이 되기 위한 유일한 조건은 술이나 약물을 끊겠다는 열망이다","근본 목적 중의 하나는 다른 알코올 의존자를 돕는 것이다","위대한 힘에 자신을 맡기며, 잘못한 일을 시인한다"]},{"name":"회복공동체","items":["구성원들은 공동체의 생활 경험을 통해서 치료를 받는다","사회적 환경이 곧 치료모델이라는 특징이 있다","참만남 프로그램, 직업재활 등의 다양한 프로그램이 제공된다","성공적인 인격의 변화에 대한 역할모델은 동료와 치료진이다"]},{"name":"NA","items":["12단계는 NA 프로그램의 핵심으로, 시행착오의 경험을 바탕으로 구성된 영적 프로그램이다","중독자는 12단계를 믿고 따를 것인가 아닌가를 선택하여 자신이 직접 실천한다"]}]},{"t":"tree","title":"자조집단","root":"자조집단","branches":[["전문가","자조집단을 있는 그대로 존중하는 태도를 가져야 한다"],["중독자","자신이 약물 사용에 있어 무기력하다는 사실을 받아들여야 한다"]]}],"15":[{"t":"flow","title":"환각물질 중독 청소년","steps":["청소년 전문치료기관에서 6개월 이내의 치료 및 재활을 받을 수 있다","3개월 범위에서 연장할 수 있다"]},{"t":"tree","title":"약물 사용 시 주의","root":"마약류관리법 등 관련 법령","branches":[["남용·의존","사용 시 남용 및 의존 가능성을 항상 염두에 두어야 한다"],["불면증 치료","1일 권장량을 초과해서는 안 된다"],["치료기간","가능한 짧아야 한다"],["만 18세 미만의 환자","투여하지 않는다"]]}],"16":[{"t":"tree","title":"고지된 동의","root":"사례관리와 상담윤리","branches":[["능력","내담자가 고지된 동의를 할 수 있는 능력이 있어야 한다"],["정보","대안적 치료의 잠재적 위해(harm)와 이익에 대해 · 객관적인 정보를 제공받아야 한다"],["취소","자신이 동의한 것을 치료중에 어느 때라도 · 취소할 자유가 있다는 것을 알고 있어야 한다"],["강요","고지된 동의를 하도록 강요받지 않아야 한다"]]}]};
