(window.TNQ=window.TNQ||[]).push({"terms":{"해시시":{"d":"대마 수지를 농축해 만든 것으로 THC 함량이 대마초보다 높은 제품입니다.","r":["THC"]},"THC":{"d":"대마의 주된 향정신성 성분으로, 감정, 인지, 지각에 영향을 주고 진통 효과를 나타낸다.","r":[]},"엔도칸나비노이드":{"d":"뇌에서 감정, 인지, 지각 등을 조절하는 체내 물질이며 THC가 이 수용체에 작용한다.","r":[]},"진해거담제":{"d":"기침을 가라앉히고 가래를 묽게 해 뱉기 쉽게 만드는 약입니다.","r":[]},"블랙아웃":{"d":"과음 중에 일어난 일이 기억나지 않는 일시적 기억 상실 상태이다.","r":[]},"갈망":{"d":"약물이나 행위에 관련된 기억, 환경 자극에 의해 유발되는 사용에 대한 강한 욕구이다.","r":[]},"금단":{"d":"사용하던 물질을 줄이거나 중단했을 때 손 떨림, 초조 같은 신체적·심리적 증상이 나타나는 상태이다.","r":[]},"내성":{"d":"약물을 반복 사용함에 따라 같은 용량으로 나타나는 효과가 점점 줄어드는 현상이다.","r":[]},"단약":{"d":"사용하던 약물을 완전히 끊는 일입니다.","r":[]},"물질사용장애":{"d":"물질 사용에도 불구하고 인지, 행동, 신체 증상이 지속되며 DSM-5에서 11가지 증상 기준으로 진단한다.","r":[]},"고지된 동의":{"d":"내담자가 상담의 목적, 절차, 한계를 충분히 설명받고 자발적으로 하는 동의이다.","r":[]},"디설피람":{"d":"알코올 분해 과정의 아세트알데히드를 체내에 남겨 음주 시 불쾌 증상을 일으켜 음주를 줄이게 하는 알코올 중독 치료약물이다.","r":[]},"메사돈":{"d":"헤로인 같은 아편계 약물중독의 대표적 치료제로, 아편계와 같은 방식으로 작용하는 대체 약물이다.","r":[]},"메스암페타민":{"d":"필로폰으로 알려진 중추신경 흥분제로, 속칭 아이스, 크리스탈로 불린다.","r":[]},"중추신경 억제제":{"d":"중추신경계의 활동을 낮추어 진정, 수면, 이완을 일으키는 약물로 알코올과 벤조디아제핀류가 있다.","r":[]},"흥분제":{"d":"중추신경계를 자극해 각성과 흥분을 높이는 약물로 코카인, 메스암페타민 등이 있다.","r":[]},"벤조디아제핀":{"d":"진정과 수면 효과를 내는 중추신경 억제제 계열 약물로 불안과 불면 치료에 쓰인다.","r":[]},"GHB":{"d":"속칭 물뽕이나 데이트 강간약으로 불리는 중추신경 억제 약물로, 알코올과 함께 쓰면 약효가 증폭된다.","r":[]},"MDMA":{"d":"식욕감퇴제로 개발되었으나 환각 효과로 남용되는 합성 약물로 속칭 엑스터시이다.","r":[]},"펜터민":{"d":"국내에서 처방 가능한 비만 치료용 식욕억제제이며 암페타민류와 연관된 교감신경 작용제이다.","r":[]},"후금단":{"d":"장기간 사용하던 약물의 중단 후 일정 기간이 지난 뒤에 나타나는 금단증상이다.","r":[]},"이중장애":{"d":"중독장애와 다른 정신장애가 함께 있는 경우이며 알코올 중독과 주요우울증의 동반이 예이다.","r":[]},"공동의존":{"d":"중독자 가족이 중독자의 문제에만 몰두하여 자존감이 낮고 정서적으로 독립하지 못하는 상태이다.","r":[]},"12단계":{"d":"AA가 사용하는 회복 프로그램으로, 무력함을 인정하고 도덕적 검토 등을 거치는 단계별 실천 방안이다.","r":[]},"Al-ateen":{"d":"알코올 중독자의 10대 자녀를 위한 자조모임이다.","r":[]},"ACOA":{"d":"알코올 중독 가정에서 성장한 성인 자녀들을 위한 자조모임이다.","r":[]},"초이론":{"d":"프로차스카가 제시한 변화단계 모형으로 행동 변화를 단계별 과정으로 설명한다.","r":[]},"FRAMES":{"d":"밀러와 산체스가 문제음주 청소년의 단기개입 요소로 제시한 피드백, 책임, 조언, 선택, 공감, 자기효능감의 약어이다.","r":[]},"집합형":{"d":"지역사회 전체가 연합하여 청소년 약물남용 예방 전략을 수행하는 예방 모델의 유형이다.","r":[]},"AUDIT":{"d":"세계보건기구가 개발한 알코올 사용장애 선별검사로 음주 문제 선별에 사용된다.","r":[]},"CAGE":{"d":"4문항으로 구성된 자기보고형 알코올 문제 선별도구이다.","r":[]},"T-ACE":{"d":"임신 중 알코올 사용 위험을 선별하기 위한 도구이다.","r":[]},"TWEAK":{"d":"임신 기간 중 알코올 남용을 평가하기 위한 선별도구이다.","r":[]},"CRAFFT":{"d":"청소년의 약물 및 알코올 문제를 선별하는 검사도구이다.","r":[]},"POSIT":{"d":"청소년의 약물사용과 관련 문제 영역을 선별하는 검사도구이다.","r":[]},"자조":{"d":"같은 문제를 가진 사람들이 전문가 주도 없이 서로 돕는 집단이며 AA와 NA가 대표적이다.","r":[]},"침습적 사고":{"d":"원하지 않는데도 반복적으로 의식에 떠오르는 외상 관련 생각이다.","r":[]},"환각제":{"d":"지각과 사고를 왜곡하는 약물로 LSD, 메스칼린이 있다.","r":[]},"플래시백":{"d":"약물 사용이나 외상 경험이 지나간 뒤에도 환각이나 장면이 갑자기 되살아나는 현상이다.","r":[]},"지남력":{"d":"시간, 장소, 사람을 올바르게 인식하는 능력이다.","r":[]},"정신운동 초조":{"d":"목적 없이 안절부절못하고 움직임이 과도하게 늘어나는 증상이다.","r":[]},"안구진탕":{"d":"눈동자가 의지와 상관없이 빠르게 떨리는 증상으로 알코올 중독 등과 관련된다.","r":[]}},"notes":{"12단계는 NA 프로그램의 핵심으로, 시행착오의 경험을 바탕으로 구성된 영적 프로그램이다":"NA는 시행착오를 겪은 사람들의 경험으로 만든 열두 단계를 중심으로 회복합니다.","12단계를 기초로 하여 알콜 없는 만족한 삶을 영위하는 방법을 제안한다":"AA는 열두 단계의 프로그램으로 술 없이 만족스럽게 사는 길을 안내합니다.","19세 이하 마약류 사범이 증가하는 추세이다":"미성년자 마약류 사범이 해마다 늘고 있다는 통계적 경향입니다.","1단계는 전 알코올 증상 단계로 사교적인 목적이며, 중독 여부와 상관이 없다":"첫 단계는 사교 목적의 음주여서 아직 중독이라고 하지 않는 시기입니다.","1일 권장량을 초과해서는 안 된다":"불면증 약은 하루 권장량을 넘기면 위험하므로 정해진 양만 복용해야 합니다.","2단계는 전조 단계로 문제성 음주 단계이며 블랙아웃이 발생하나, 술의 문제에 대해서는 부인한다":"문제 음주로 기억이 끊기기 시작하지만 본인은 술 문제를 인정하지 않는 단계입니다.","2문항 이상 ‘그렇다’라고 응답하면 알코올의존으로 선별된다":"두 개 이상에 그렇다고 답하면 알코올의존이 의심되어 추가 평가 대상이 됩니다.","3개월 범위에서 연장할 수 있다":"필요하면 치료 기간을 석 달 안에서 늘릴 수 있습니다.","3단계는 결정적 단계로 음주에 대한 통제력 상실이 나타난다":"한 잔만 마셔도 멈추지 못하는 통제력 상실이 생기면서 진짜 중독으로 들어서는 단계입니다.","DSM-Ⅳ의 물질남용과 물질의존":"이전 DSM에서는 물질남용과 물질의존이 서로 다른 진단이었습니다.","THC는 엔도칸나비노이드(endocannabinoids) 수용체에 작용하며 감정, 인지, 지각 등에 영향을 미친다":"THC는 뇌의 칸나비노이드 수용체에 붙어 기분과 사고와 감각을 바꿉니다.","‘누바인’으로 불리며, 의료용 진통제로 사용한다":"이 약물의 상품명은 누바인이며 병원에서 진통 목적으로 쓰이는 마약성 진통제입니다.","‘러미나’로 불리며, 진해거담제로 사용한다":"덱스트로메토르판은 기침약 성분이지만 고용량을 남용하면 환각 효과가 나타납니다.","‘필로폰’으로 알려져 있으며, ‘아이스’, ‘크리스탈’로 불린다":"메스암페타민은 이런 은어로 유통되는 중추신경 흥분제입니다.","간편하게 알코올의존을 선별할 수 있는 측정도구이다":"짧은 질문만으로 알코올의존 가능성이 있는 사람을 가려내는 선별 도구입니다.","갈망을 다루기 위해 사용되는 방법이다":"약물을 하고 싶은 욕구가 올라올 때 다른 활동으로 주의를 돌려 넘기는 방법입니다.","감정 조절 어려움은 약물사용의 위험요소로 작용할 수 있다":"감정을 다스리기 힘든 사람은 불쾌한 기분을 약물로 풀려고 하기 쉽습니다.","개인상담보다 비용과 시간 측면에서 경제적일 수 있다":"한 번에 여러 사람을 상담하므로 개인상담보다 비용과 시간이 덜 듭니다.","객관적인 정보를 제공받아야 한다":"치료 방법마다 있을 수 있는 해와 득을 치우침 없이 알려 줘야 합니다.","고지된 동의를 하도록 강요받지 않아야 한다":"압박이나 위협 없이 자유로운 의사로 동의해야 그 동의가 효력을 가집니다.","공감과 염려의 태도, 존중하는 목소리로 살피면서 진행한다":"진행자는 따뜻하고 걱정하는 태도로 집단원을 존중하며 이끌어야 합니다.","구성원들은 공동체의 생활 경험을 통해서 치료를 받는다":"치료 효과는 약이나 상담만이 아니라 함께 사는 생활 자체에서 나옵니다.","구성원이 되기 위한 유일한 조건은 술이나 약물을 끊겠다는 열망이다":"가입에 다른 자격은 필요하지 않고 술을 끊고 싶은 마음만 있으면 됩니다.","근본 목적 중의 하나는 다른 알코올 의존자를 돕는 것이다":"회복한 구성원이 아직 힘든 사람을 도우면서 자신의 회복도 유지합니다.","내담자가 고지된 동의를 할 수 있는 능력이 있어야 한다":"내담자가 내용을 이해하고 판단할 수 있는 상태여야 동의가 유효합니다.","다른 사람의 회복과정을 목격함으로써 단약 동기를 가질 수 있다":"회복해 가는 동료를 보면서 자신도 약을 끊을 수 있다는 의욕이 생깁니다.","다른 집단원들로부터 자신의 생각에 대해서 피드백을 받고 약물사용에 대한 왜곡된 신념을 발견할 수 있다":"다른 성원의 반응을 들으며 약물에 대한 그릇된 믿음을 스스로 깨닫습니다.","다크웹, SNS를 통한 접근성이 높아졌다":"인터넷의 익명 공간과 소셜미디어를 통해 마약을 구하기가 쉬워졌습니다.","단약에 대한 내담자의 실수를 소중한 배움의 경험으로 연결되도록 한다":"끊는 과정에서 생기는 실수를 실패로 낙인찍지 않고 배움의 기회로 삼도록 이끕니다.","담배 사용을 조절하려는 노력에도 불구하고 실패한다":"줄이려고 해 봐도 뜻대로 되지 않는 조절 실패가 진단 기준에 들어갑니다.","담배에 대한 갈망감 혹은 욕구가 있다":"담배를 피우고 싶은 강한 욕구가 있는 것은 담배 사용장애의 진단 기준 가운데 하나입니다.","대마 성분 중 CBD(Cannabidiol)는 의료용으로 사용된다":"대마에서 얻는 CBD는 환각 작용이 약해 일부 질환의 치료에 쓰입니다.","대마초보다 해시시가 THC 함유량이 더 높다":"해시시는 대마 수지를 농축한 것이어서 같은 양에 THC가 더 많이 들어 있습니다.","대안적 치료의 잠재적 위해(harm)와 이익에 대해":"내담자가 치료의 위험과 이익에 관해 어떤 정보를 받아야 하는지 설명하는 문장의 앞부분입니다.","동료 간의 직면을 특정 사람을 집단으로부터 밀어내는 도구로 사용하지 않아야 한다":"직면이 한 사람을 따돌리는 수단이 되지 않도록 진행자가 막아야 합니다.","동일량의 담배를 사용하지만 그 효과가 현저히 감소한다":"이는 내성에 해당하여 같은 양으로는 예전만큼 만족을 얻지 못합니다.","만성적인 대마초 오남용은 조현병과 같은 정신질환을 유발할 가능성을 높인다":"대마초를 오래 과하게 쓰면 조현병 같은 정신 질환에 걸릴 위험이 높아집니다.","모르핀보다 약 100배 정도의 강력한 진통효과를 가진다":"펜타닐은 같은 양으로 모르핀보다 백 배쯤 강하게 통증을 억제합니다.","물질 사용을 줄이거나 습관적 행위 등을 중단할 때 나타나는 증상":"금단은 쓰던 것을 끊거나 줄였을 때 몸과 마음에 생기는 불쾌한 반응입니다.","물질사용장애로 일원화 하였다":"이후 개정에서는 두 진단을 하나로 합쳐 증상의 수로 심각도를 나눕니다.","물질을 과도하게 사용해서 남용의 부작용과 함께 내성과 금단증상으로 표현되는 상태":"의존은 남용에 따른 문제에 더해 내성이 생기고 끊으면 금단이 나타나는 단계입니다.","밀조된 펜타닐은 정확한 함량을 지키지 않아 더욱 위해하다":"불법으로 만든 제품은 성분량이 일정하지 않아 사용자가 용량을 가늠하기 어렵습니다.","법과 제도의 개선, 취약성 폐해 홍보 및 예방교육 프로그램 등이 포함된다":"예방교육에는 제도 정비와 위험을 알리는 홍보, 교육 프로그램이 모두 들어갑니다.","본래는 비활성이었다가 인체 내 효소에 의해 대사된 후 활성화되는 약물":"먹을 때는 효과가 없다가 몸속 효소가 변환시킨 뒤에야 작용하는 약물을 가리킵니다.","사용 시 남용 및 의존 가능성을 항상 염두에 두어야 한다":"처방받은 약도 계속 쓰면 남용과 의존으로 이어질 수 있어 늘 경계해야 합니다.","사용위험이나 취약성을 감소시키고, 보호요인을 증가시키는 가장 이상적인 예방방법이다":"위험을 줄이고 약물로부터 지켜 주는 요인을 키운다는 점에서 이상적인 예방 방법이라 합니다.","사회적 환경이 곧 치료모델이라는 특징이 있다":"공동체 안의 관계와 규칙 같은 사회적 환경이 치료의 핵심 수단입니다.","성공적인 인격의 변화에 대한 역할모델은 동료와 치료진이다":"변화한 선배 구성원과 치료진이 본보기가 되어 새로운 행동을 배웁니다.","소량을 흡입해도 인체에 치명적이다":"효과가 워낙 강해 아주 적은 양만으로도 호흡이 멈출 수 있습니다.","술 냄새가 나지 않는데도 술 취한 사람처럼 비틀거리기도 한다":"흡입제의 영향으로 알코올 없이도 취한 것 같은 걸음걸이를 보일 수 있습니다.","식욕감퇴제로 개발되었으며, ‘도리도리’, ‘엑스터시’로 불린다":"MDMA는 원래 식욕을 줄이는 약으로 개발되었으나 지금은 이런 은어로 불리는 마약입니다.","식욕억제제, 마취제 등 의료용 마약류의 남용이 늘어나고 있다":"병원에서 쓰는 약이 처방 목적을 벗어나 오남용되는 사례가 늘고 있습니다.","신종 마약류 적발이 증가하고 있다":"기존 규제 목록에 없던 새로운 종류의 마약류가 적발되는 일이 늘고 있습니다.","알코올 중독이 진행성 질병이라고 주장한다":"젤리넥은 알코올 중독을 시간이 갈수록 단계적으로 악화되는 질병으로 보았습니다.","약물경험이 있는 또래들과 함께 지내며 약물을 줄이려는 경향이 강해 집단상담이 유용할 수 있다":"같은 경험을 한 또래끼리 모이면 서로 영향을 받아 약물을 줄이려는 분위기가 형성됩니다.","약물 또는 행위에 관련된 기억, 환경 자극에 의해 유발되는 조건화된 반응":"약물을 쓰던 장소나 사람 같은 단서를 마주하면 학습된 반응으로 강한 욕구가 일어납니다.","약물사용과 관련된 ‘지금-여기’의 주제에 대해 초점을 맞춘다":"과거 이야기보다 현재 집단에서 일어나는 약물 관련 문제를 다룹니다.","약물에서 회복하도록 돕는 것과 일상생활을 잘하도록 하는 것이다":"인지행동상담은 약물을 끊게 하는 일과 평소 생활 기능을 되찾게 하는 일을 기본 과제로 합니다.","예방효과를 높이기 위해서는 평생교육이 중요하다":"한 번의 교육으로 끝내지 말고 생애 전반에 걸쳐 되풀이해야 효과가 지속됩니다.","위대한 힘에 자신을 맡기며, 잘못한 일을 시인한다":"단계의 내용으로, 자신보다 큰 힘에 의지하고 지난 잘못을 인정하는 과정이 들어 있습니다.","위험성에 노출되지 않은 사람들을 대상으로 한다는 점에서 사용예방이라고도 불린다":"아직 약물을 접하지 않은 사람에게 처음부터 쓰지 않게 하려는 교육이라 사용예방이라고도 합니다.","음주문제 선별을 위한 1차적 검사도구로 사용되고 있다":"확정 진단을 위한 검사가 아니라 처음 단계에서 음주 문제가 있는지 가려내는 용도입니다.","의료용 진통제로 개발된 합성 마약이다":"펜타닐은 통증을 줄이려고 만든 약이지만 합성 마약으로 분류되어 남용 위험이 큽니다.","일관성 없는 양육태도를 가지고 있을 가능성이 높다":"부모가 중독이면 아이를 대하는 태도가 때에 따라 달라져 자녀가 정서적으로 불안해집니다.","자기보고형 측정도구 4문항으로 구성되어 있다":"응답자가 스스로 답하는 방식이며 네 개의 질문으로만 이루어집니다.","자신이 동의한 것을 치료중에 어느 때라도":"내담자의 동의 철회 자유를 설명하는 문장의 앞부분입니다.","자신이 보호 받아야 할 어린아이라고 생각할 때 외로움을 느낀다":"보살핌을 받지 못한 경험 때문에 자신을 돌봄이 필요한 존재로 느끼는 순간 외로움이 커집니다.","자신이 약물 사용에 있어 무기력하다는 사실을 받아들여야 한다":"약물을 혼자 힘으로 통제할 수 없다는 점을 인정하는 것이 회복의 출발입니다.","자조집단을 있는 그대로 존중하는 태도를 가져야 한다":"전문가는 자조집단의 방식에 개입하거나 평가하지 않고 그대로 인정해야 합니다.","중독을 유발할 수 있는 물질에 알코올, 담배, 카페인, 수면제 등이 포함되어 있다":"중독 물질에는 마약 외에도 일상에서 흔히 쓰는 술과 담배와 카페인이 들어갑니다.","중독자는 12단계를 믿고 따를 것인가 아닌가를 선택하여 자신이 직접 실천한다":"단계를 따를지는 본인이 스스로 정하고 직접 실천하는 자발적 프로그램입니다.","증상수에 따라 경도, 중등도, 고도로 분류한다":"해당하는 증상이 많을수록 더 높은 심각도로 구분합니다.","집단상담에서 약물남용으로부터 회복을 간접체험 할 수 있다":"다른 성원의 회복담을 들으면서 자신의 회복 과정을 미리 그려 볼 수 있습니다.","집단에서 규칙을 지킴으로써 살아가는 방식을 배울 수 있다":"집단의 규칙을 따르는 경험이 사회생활의 요령을 익히는 기회가 됩니다.","참만남 프로그램, 직업재활 등의 다양한 프로그램이 제공된다":"솔직한 자기 개방을 돕는 집단 활동과 일을 준비하는 재활 프로그램이 함께 운영됩니다.","참여자의 고립감을 해소시켜 주고 안정감을 더할 수 있다":"나만 이런 문제를 겪는 것이 아니라는 느낌이 외로움을 덜어 마음을 안정시킵니다.","청소년들이 SNS, 포털사이트 검색 등에 쉽게 노출되어 호기심으로 구입하는 사례가 증가하고 있다":"온라인에서 쉽게 정보를 접한 청소년이 호기심으로 마약을 사는 경우가 늘고 있습니다.","청소년 마약류 사범이 증가하고 있다":"마약류 범죄로 적발되는 청소년의 수가 늘어나는 추세입니다.","청소년의 음주에 대한 태도와 규범에 영향을 줄 수도 있다":"부모가 술 마시는 모습을 보고 자란 청소년은 음주를 허용적으로 받아들이기 쉽습니다.","청소년 전문치료기관에서 6개월 이내의 치료 및 재활을 받을 수 있다":"환각물질 중독 청소년은 전문 기관에서 여섯 달 안에서 치료와 재활을 받을 수 있습니다.","충혈된 눈, 잦은 눈물, 손, 발 등의 경미한 떨림을 보이기도 한다":"약물 영향으로 눈과 손발에 이런 신체 이상 징후가 나타납니다.","취소할 자유가 있다는 것을 알고 있어야 한다":"한 번 동의했어도 치료 중에 언제든 철회할 수 있음을 내담자가 알아야 합니다.","친구를 초대하지 않고, 친구 집에 놀러가지도 않는다":"집안 문제를 숨기려고 친구와 집을 오가는 일을 피합니다.","태아일 때부터 약물이나 알콜에 노출되었을 가능성이 있다":"임신 중 어머니의 약물이나 음주가 태아의 발달에 영향을 주었을 수 있습니다.","투약사범이 밀수사범보다 많다":"적발된 사람 중 직접 투약한 사람이 밀수한 사람보다 더 많습니다.","행복한 가정에 사는 친구를 시기한다":"공동의존 가정의 아동은 화목한 친구 가정을 부러워하며 질투하는 감정을 보입니다.","향정신성의약품이 마약의 검거율보다 높다":"단속된 건수에서 향정신성의약품 사범이 마약 사범보다 많다는 통계입니다.","환각흡입 물질이나 빨대, 비닐봉지 등이 발견되는 경우가 있다":"흡입 약물을 사용한 흔적으로 방 안에서 관련 도구가 나올 수 있습니다.","회복된 이후에 중독 증상이 다시 나타나는 것":"한동안 끊었다가 다시 문제 사용으로 돌아가는 일이 재발입니다.","횡설수설하며 폭력적인 언행이 증가한다":"환각물질 사용 중에는 말이 앞뒤가 맞지 않고 거칠어지는 모습이 보입니다."}});if(window.DIAGRAM&&DIAGRAM.tnFlush)DIAGRAM.tnFlush();
